package io.github.keplersj.selkie.proot

import android.os.SystemClock
import android.system.ErrnoException
import android.system.Os
import io.github.keplersj.selkie.engine.EngineEnv
import io.github.keplersj.selkie.engine.ShellSpec
import java.io.File

/**
 * Creates the host-side files and directories that [ProotCommandBuilder] binds into the guest.
 * Content here is generated by Selkie (not copied from any other project).
 */
object GuestFiles {
    /**
     * `/proc/sys` values Android hides from apps, as a stock 64-bit Linux reports them (#15). bubblewrap
     * reads overflowuid before anything else, libcap sizes capability sets from cap_last_cap, and file
     * watchers, JVMs and databases read the limits. User namespaces are reported off, which is the truth
     * under Android's seccomp policy and lets tools fail fast.
     */
    val PROC_SYS_DEFAULTS: Map<String, String> = linkedMapOf(
        "/proc/sys/kernel/overflowuid" to "65534",
        "/proc/sys/kernel/overflowgid" to "65534",
        "/proc/sys/kernel/pid_max" to "4194304",
        "/proc/sys/kernel/ngroups_max" to "65536",
        "/proc/sys/kernel/cap_last_cap" to "40",
        "/proc/sys/kernel/unprivileged_userns_clone" to "0",
        "/proc/sys/user/max_user_namespaces" to "0",
        "/proc/sys/fs/file-max" to "9223372036854775807",
        "/proc/sys/fs/inotify/max_user_watches" to "65536",
        "/proc/sys/vm/overcommit_memory" to "0",
        "/proc/sys/net/core/somaxconn" to "4096",
    )

    /** Entries Android commonly hides from apps; we only fake the ones we cannot read. */
    val FAKE_PROC_ENTRIES = listOf("/proc/stat", "/proc/version", "/proc/loadavg", "/proc/uptime") +
        PROC_SYS_DEFAULTS.keys + listOf("/proc/sys/kernel/osrelease", "/proc/sys/kernel/hostname")

    /** The host kernel's `uname` release and version, which `/proc/version` must agree with (#10). */
    data class Kernel(val release: String, val version: String)

    fun hostKernel(): Kernel = Os.uname().let { Kernel(it.release, it.version) }

    fun prepare(
        env: EngineEnv,
        spec: ShellSpec,
        readable: (String) -> Boolean = { canRead(it) },
        uptimeSeconds: Double = SystemClock.elapsedRealtime() / 1000.0,
        cpus: Int = Runtime.getRuntime().availableProcessors(),
        chmod: (File, Int) -> Unit = { f, mode -> Os.chmod(f.path, mode) },
        kernel: () -> Kernel = { hostKernel() },
    ): Map<String, File> {
        listOf(env.guestTmp, env.guestRun, env.guestShm, env.guestCgroup, env.guestGenerated, env.prootTmp,
            env.prootL2s, env.usbDevDir, env.usbSysDir)
            .forEach { it.mkdirs() }
        // Binds whose guest path is under /run need their mount point to exist in the writable dir.
        for (b in spec.binds) if (b.guest.startsWith("/run/")) {
            File(env.guestRun, b.guest.removePrefix("/run/")).mkdirs()
        }
        File(env.guestRun, "droidc").mkdirs()
        // XDG_RUNTIME_DIR: created here (0700) so the compositor can listen in it before the guest starts.
        env.guestRuntimeDir.mkdirs()
        env.guestRuntimeDir.setReadable(false, false); env.guestRuntimeDir.setReadable(true, true)
        env.guestRuntimeDir.setWritable(false, false); env.guestRuntimeDir.setWritable(true, true)
        env.guestRuntimeDir.setExecutable(false, false); env.guestRuntimeDir.setExecutable(true, true)
        // /tmp and /dev/shm are 1777 on any Linux host. java.io.File cannot set the sticky bit (setWritable
        // only adds w bits, which made /tmp 0722), so Os.chmod; 0777 if the filesystem refuses S_ISVTX.
        for (d in listOf(env.guestTmp, env.guestShm)) {
            try { chmod(d, STICKY_WORLD) } catch (_: ErrnoException) {
                try { chmod(d, 0x1ff) } catch (_: ErrnoException) {}
            }
        }
        File(env.guestGenerated, "resolv.conf").writeText(resolvConf(env.dns))

        val out = linkedMapOf<String, File>()
        val k by lazy { try { kernel() } catch (_: Exception) { Kernel("", "") } }
        for (guest in FAKE_PROC_ENTRIES) {
            if (readable(guest)) continue
            val f = fakeProcFile(env, guest)
            f.writeText(fakeProcContent(guest, uptimeSeconds, cpus, env.hostname, k))
            out[guest] = f
        }
        return out
    }

    /** Where the generated content for a faked `/proc` entry lives on the host. */
    fun fakeProcFile(env: EngineEnv, guest: String): File =
        File(env.guestGenerated, "proc" + guest.removePrefix("/proc").replace('/', '_'))

    /**
     * Rewrites a container's fake `/proc/uptime`, if it has one, so it advances while sessions run (#15).
     * Binds read the host file on every open, but procps keeps the file open and seeks back to 0, so it
     * is rewritten in place. Uptime only grows, so the new text is never shorter and a reader never sees
     * a stale tail.
     */
    fun refreshUptime(env: EngineEnv, uptimeSeconds: Double, cpus: Int) {
        val f = fakeProcFile(env, "/proc/uptime")
        if (!f.isFile) return
        val bytes = fakeProcContent("/proc/uptime", uptimeSeconds, cpus).toByteArray()
        try {
            java.io.RandomAccessFile(f, "rw").use { it.seek(0); it.write(bytes); it.setLength(bytes.size.toLong()) }
        } catch (_: Exception) {}
    }

    /**
     * Hides Android's SELinux from the guest. It is visible but off limits to apps, so libselinux in the
     * guest (dbus-daemon, dbus-broker) believes SELinux is on, cannot read `/sys/fs/selinux/enforce` and
     * aborts. libselinux first `statfs`es `/sys/fs/selinux` for the SELinux magic, then falls back to
     * `/proc/filesystems`, so both are overridden: an empty directory over `/sys/fs/selinux`, and a
     * `/proc/filesystems` without `selinuxfs` (apps usually cannot read the host's, so [FALLBACK_FILESYSTEMS]
     * is used then). The guest then behaves as on a host without SELinux.
     */
    fun prepareSelinuxHiding(
        env: EngineEnv,
        read: () -> String = { File("/proc/filesystems").readText() },
    ): Map<String, File> {
        env.guestGenerated.mkdirs()
        val f = File(env.guestGenerated, "proc_filesystems")
        f.writeText(withoutSelinuxfs(try { read() } catch (_: Exception) { FALLBACK_FILESYSTEMS }))
        val empty = File(env.guestGenerated, "empty").apply { mkdirs() }
        return mapOf("/proc/filesystems" to f, "/sys/fs/selinux" to empty)
    }

    val FALLBACK_FILESYSTEMS = listOf(
        "nodev\tsysfs", "nodev\ttmpfs", "nodev\tproc", "nodev\tdevpts", "nodev\tcgroup", "nodev\tcgroup2",
        "nodev\tfuse", "\text4", "\tf2fs", "\tvfat",
    ).joinToString("\n", postfix = "\n")

    fun withoutSelinuxfs(content: String): String =
        content.lines().filterNot { it.trim().endsWith("selinuxfs") }.joinToString("\n").trimEnd('\n') + "\n"

    /**
     * Generates `/etc/passwd` and `/etc/group` for the guest: the image's own files plus an entry for the app
     * uid/gid, which Android assigns per install and no image knows about. Without it `id`, `getpwuid` and
     * dbus-broker fail. Returns guest path -> host file, to be bound over the image's files. Regenerated on
     * every launch from the image's current files, so image upgrades never conflict with it.
     */
    fun prepareIdentity(env: EngineEnv, spec: ShellSpec): Map<String, File> {
        env.guestGenerated.mkdirs()
        val etc = File(spec.rootfs, "etc")
        val home = spec.env["HOME"] ?: "/root"
        val passwd = File(env.guestGenerated, "passwd")
        val group = File(env.guestGenerated, "group")
        passwd.writeText(passwdWithUser(readOrEmpty(File(etc, "passwd")), env.uid, env.gid, home))
        group.writeText(groupWithGid(readOrEmpty(File(etc, "group")), env.gid))
        val hostname = File(env.guestGenerated, "hostname").apply { writeText(env.hostname + "\n") }
        val out = linkedMapOf("/etc/passwd" to passwd, "/etc/group" to group, "/etc/hostname" to hostname)
        localtime(env, spec)?.let { out["/etc/localtime"] = it }
        return out
    }

    /**
     * The guest's `/etc/localtime`: a copy of the image's own zoneinfo file for the device's time zone.
     * bootc images ship without one (first boot or `timedatectl` makes it), and glib, GNOME and Java read
     * the file rather than `$TZ`. A copy, not a symlink, because the bind is resolved on the host. Null
     * when the id is not a plain zoneinfo path or the image has no tzdata for it; `TZ` still applies.
     */
    fun localtime(env: EngineEnv, spec: ShellSpec): File? {
        if (!isZoneId(env.timeZone)) return null
        val zone = File(spec.rootfs, "usr/share/zoneinfo/${env.timeZone}")
        if (!zone.isFile) return null
        val out = File(env.guestGenerated, "localtime")
        return try { zone.copyTo(out, overwrite = true) } catch (_: Exception) { null }
    }

    /**
     * Environment from the device for every guest process: `TZ` and `LANG`. The image's own values win
     * (see [ProotCommandBuilder.environment]). `LANG` is the device locale when the image has it (a
     * `/usr/lib/locale/<ll_CC>.utf8` directory, as Fedora's langpacks install, or a locale archive) and
     * `C.UTF-8`, which glibc always has, otherwise, so programs never fall back to ASCII.
     */
    fun guestEnv(env: EngineEnv, spec: ShellSpec): Map<String, String> = buildMap {
        if (isZoneId(env.timeZone)) put("TZ", env.timeZone)
        put("LANG", guestLang(File(spec.rootfs), env.locale))
    }

    fun guestLang(rootfs: File, locale: String): String {
        if (!Regex("[a-z]{2,3}(_[A-Z]{2})?").matches(locale)) return "C.UTF-8"
        val dir = File(rootfs, "usr/lib/locale")
        val have = File(dir, "$locale.utf8").isDirectory || File(dir, "locale-archive").isFile
        return if (have) "$locale.UTF-8" else "C.UTF-8"
    }

    /** `Area/City` style ids only: no `..`, no leading `/`, nothing the zoneinfo tree could not hold. */
    fun isZoneId(id: String): Boolean = Regex("[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)*").matches(id)

    private const val STICKY_WORLD = 0x3ff // 01777

    /** [base] plus `selkie:x:<uid>:<gid>:Selkie:<home>:/bin/bash`, unless the uid is already present. */
    fun passwdWithUser(base: String, uid: Int, gid: Int, home: String): String =
        withEntry(base, 2, uid, "selkie:x:$uid:$gid:Selkie:$home:/bin/bash")

    /** [base] plus `selkie:x:<gid>:`, unless the gid is already present. */
    fun groupWithGid(base: String, gid: Int): String = withEntry(base, 2, gid, "selkie:x:$gid:")

    private fun withEntry(base: String, idField: Int, id: Int, entry: String): String {
        val lines = base.lines().filter { it.isNotEmpty() }
        val taken = lines.any { it.split(':').getOrNull(idField)?.toIntOrNull() == id }
        return (if (taken) lines else lines + entry).joinToString("\n", postfix = "\n")
    }

    private fun readOrEmpty(f: File): String = try { f.readText() } catch (_: Exception) { "" }

    fun resolvConf(dns: List<String>): String =
        (dns.ifEmpty { listOf("1.1.1.1", "8.8.8.8") }).joinToString("\n", postfix = "\n") { "nameserver $it" }

    fun fakeProcContent(
        guest: String,
        uptime: Double,
        cpus: Int,
        hostname: String = "selkie",
        kernel: Kernel = Kernel("", ""),
    ): String = when (guest) {
        "/proc/uptime" -> "%.2f %.2f\n".format(java.util.Locale.ROOT, uptime, uptime * cpus * 0.9)
        "/proc/loadavg" -> "0.10 0.10 0.10 1/200 1000\n"
        // Same release and version as uname(2), which proot does not fake.
        "/proc/version" -> if (kernel.release.isEmpty()) "Linux version unknown (selkie@android) #1 SMP PREEMPT\n"
            else "Linux version ${kernel.release} (selkie@android) ${kernel.version}\n"
        "/proc/sys/kernel/osrelease" -> kernel.release + "\n"
        "/proc/sys/kernel/hostname" -> hostname + "\n"
        in PROC_SYS_DEFAULTS -> PROC_SYS_DEFAULTS.getValue(guest) + "\n"
        "/proc/stat" -> buildString {
            val jiffies = (uptime * 100).toLong()
            append("cpu  ${jiffies / 10} 0 ${jiffies / 20} ${jiffies * cpus} 0 0 0 0 0 0\n")
            for (i in 0 until cpus) append("cpu$i ${jiffies / 10 / cpus} 0 ${jiffies / 20 / cpus} ${jiffies} 0 0 0 0 0 0\n")
            append("intr 0\nctxt ${jiffies * 10}\nbtime ${System.currentTimeMillis() / 1000 - uptime.toLong()}\n")
            append("processes ${jiffies / 5}\nprocs_running 1\nprocs_blocked 0\n")
        }
        else -> ""
    }

    private fun canRead(path: String): Boolean = try {
        File(path).bufferedReader().use { it.read() }
        true
    } catch (_: Exception) { false }
}
